#include "tigersheets/workbook_tools.hpp"
#include "tigersheets/calculation.hpp"
#include <cmath>
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
namespace {
void require(bool condition,const char* message){if(!condition)throw std::runtime_error(message);}
Json book(){return Json::parse(R"json({"revision":0,"sheets":[{"id":"s","name":"Model","cells":[{"row":1,"col":1,"input":"10"},{"row":1,"col":2,"input":"2"},{"row":1,"col":3,"input":"=A1*B1"}]},{"id":"r","name":"Financial Reports","cells":[]}]})json");}
Json scenario(){return {{"version",1},{"id","upside"},{"name","Upside inputs"},{"kind","scenario"},{"cells",Json::array({{{"sheet","s"},{"row",1},{"col",1},{"type","number"},{"value",20}}})}};}
void host(WorkbookTools& tools){tools.calculationContextIsCurrent=[](std::uint64_t generation){return generation==17;};tools.calculate=[](const Json& candidate){auto value=CalculationEngine().calculate(candidate);value["calculationContext"]={{"generation",17},{"allowCachedLinks",false},{"links",Json::array()},{"diagnostics",Json::array()}};return value;};}
void typedSave(){WorkbookSession session(book());WorkbookTools tools(session,Json::object());host(tools);const auto before=session.snapshot();
 const auto reply=tools.invoke("workbook_v1_preview",{{"revision",0},{"operations",Json::array({{{"type","save_financial_model"},{"definition",scenario()}}})}});
 require(reply.value("status",std::string())=="preview","Typed financial save must create an isolated proposal");require(session.snapshot()==before&&!session.snapshotView().contains("financialModels"),"Saving a configuration must retain canonical source and metadata until acceptance");require(session.previewView()->at("financialModels")[0].at("id")=="upside"&&session.previewView()->at("sheets")[0].at("cells")[0].at("input")=="10","Saving a scenario must retain inputs until explicit scenario application");
 require(session.accept()&&session.snapshotView().at("financialModels").size()==1,"Financial save accepts once");require(session.undo()&&!session.snapshotView().contains("financialModels"),"One undo removes the saved configuration");
}
void boundedReads(){auto source=book();auto saved=scenario();saved["cache"]={{"records",std::string(2000000,'x')}};saved["results"]=std::string(2000000,'y');source["financialModels"]=Json::array({saved});for(int index=0;index<300;++index)source["financialModels"].push_back({{"version",7},{"id","future"+std::to_string(index)},{"name","Future"+std::to_string(index)},{"kind","future"}});source["financialModels"][1]["cache"]=saved["cache"];WorkbookSession session(source);WorkbookTools tools(session,Json::object());
 auto listed=tools.invoke("workbook_v1_financial_models",{{"limit",200}});require(!listed.contains("error")&&listed.at("models").size()==200&&listed.at("total")==301&&listed.at("truncated")==true&&listed.dump().size()<1048576,"Financial discovery must paginate without transferring source caches");require(!listed.at("models")[0].contains("cache")&&!listed.at("models")[0].contains("cells"),"Financial summaries cannot include source/cache payloads");
 auto read=tools.invoke("workbook_v1_financial_model",{{"id","upside"}});require(!read.contains("error")&&read.at("definition").at("cells")==scenario().at("cells")&&!read.at("definition").contains("cache")&&!read.at("definition").contains("results")&&read.at("readOnly")==false,"Single financial reads retain a complete editable definition and omit generated/internal payloads");
 auto future=tools.invoke("workbook_v1_financial_model",{{"id","future0"}});require(!future.contains("error")&&future.at("readOnly")==true&&!future.at("definition").contains("cache"),"Unsupported future definitions remain preserved and readable only as bounded identities");
 auto page=tools.invoke("workbook_v1_financial_models",{{"kind","future"},{"offset",299},{"limit",1}});require(page.at("models").size()==1&&page.at("models")[0].at("id")=="future299"&&page.at("total")==300&&!page.at("truncated").get<bool>(),"Financial reads search the complete definition set with kind filtering and offsets");require(tools.invoke("workbook_v1_financial_models",{{"limit",201}}).contains("error"),"Financial list limits are enforced");require(session.snapshot()==source,"Bounded financial inspection never rewrites preserved metadata");
}
Json forecast(){return {{"version",1},{"id","revenue"},{"name","Revenue forecast"},{"kind","forecast"},{"periods",2},{"startPeriod",2027},{"drivers",Json::array({{{"name","Revenue"},{"base",{{"sheet","s"},{"row",1},{"col",1}}},{"growth",0.1},{"numberFormat","#,##0.00"}}})},{"output",{{"sheet","r"},{"row1",1},{"col1",1}}}};}
void typedLifecycle(){WorkbookSession session(book());WorkbookTools tools(session,Json::object());host(tools);const auto before=session.snapshot();
 auto reply=tools.invoke("workbook_v1_preview",{{"revision",0},{"operations",Json::array({{{"type","set_cell"},{"sheet","s"},{"row",1},{"col",1},{"input","12"}},{{"type","run_financial_model"},{"definition",forecast()}},{{"type","save_financial_model"},{"definition",scenario()}},{{"type","apply_financial_scenario"},{"id","upside"}}})}});
 if(reply.contains("error"))std::cerr<<reply.dump()<<'\n';require(reply.value("status",std::string())=="preview","Typed report run and scenario application must compose with ordinary edits");require(session.snapshot()==before,"Running financial models never changes the live workbook before acceptance");const auto* preview=session.previewView();require(preview&&preview->at("financialModels").size()==2&&preview->at("sheets")[0].at("cells")[0].at("input")=="20","The proposal contains generated report metadata and applied saved input values");require(std::abs(preview->at("financialModels")[0].at("results")[0][0].get<double>()-13.2)<1e-10,"Forecast generation uses preceding proposed source changes");
 auto model=tools.invoke("workbook_v1_financial_model",{{"id","revenue"}});require(model.at("view")=="preview"&&!model.at("definition").at("output").contains("row2"),"Financial definition reads use the proposal and omit owned generated extent");
 require(tools.invoke("workbook_v1_preview",{{"revision",0},{"operations",Json::array({{{"type","run_financial_model"},{"id","revenue"}}})}}).value("status",std::string())=="preview","Saved report refresh is supported by id");require(session.previewView()->at("financialModels")[0].at("results")[0][0]==22.0,"A saved run reuses current proposed inputs");
 auto prior=*session.previewView();require(tools.invoke("workbook_v1_preview",{{"revision",0},{"operations",Json::array({{{"type","run_financial_model"},{"id","revenue"},{"definition",forecast()}}})}}).contains("error")&&*session.previewView()==prior,"Run requires exactly one identity or definition and refuses atomically");
 require(session.accept()&&session.undo()&&session.snapshotView().at("sheets")==before.at("sheets")&&!session.snapshotView().contains("financialModels"),"An accumulated financial proposal is one accepted undo transaction");
 WorkbookSession deletion(before);WorkbookTools remove(deletion,Json::object());host(remove);require(remove.invoke("workbook_v1_preview",{{"revision",0},{"operations",Json::array({{{"type","run_financial_model"},{"definition",forecast()}},{{"type","delete_financial_model"},{"id","revenue"}}})}}).value("status",std::string())=="preview","Typed report deletion composes after creation");require(deletion.previewView()->at("financialModels").empty()&&deletion.previewView()->at("sheets")[1].at("cells").empty(),"Deletion clears generated owned cells and metadata together");
 require(remove.invoke("workbook_v1_preview",{{"revision",0},{"operations",Json::array({{{"type","save_financial_model"},{"definition",forecast()}}})}}).contains("error"),"Generated reports require run rather than standalone configuration save");
}
Json goal(){return {{"version",1},{"id","target-profit"},{"name","Target profit"},{"kind","goal_seek"},{"specification",{{"output",{{"sheet","s"},{"row",1},{"col",3}}},{"changing",{{"sheet","s"},{"row",1},{"col",1}}},{"target",50},{"lower",0},{"upper",100}}}};}
Json run(WorkbookTools& tools,const Json& definition){return tools.invoke("workbook_v1_preview",{{"revision",0},{"operations",Json::array({{{"type","run_financial_model"},{"definition",definition}}})}});}
void numericalAndContext(){
 WorkbookSession numerical(book());WorkbookTools tools(numerical,Json::object());host(tools);auto response=run(tools,goal());require(response.value("status",std::string())=="preview"&&response.at("financialResults")[0].at("analysis").at("success")==true,"Qualified numerical results are exposed as reviewable financial analysis");require(std::abs(std::stod(numerical.previewView()->at("sheets")[0].at("cells")[0].at("input").get<std::string>())-25)<1e-8&&numerical.snapshotView().at("sheets")[0].at("cells")[0].at("input")=="10","Goal Seek offers its solved constant only in the proposal");
 auto solver=goal();solver["id"]="solver-profit";solver["name"]="Solver profit";solver["kind"]="solver";solver["specification"]={{"objective",{{"sheet","s"},{"row",1},{"col",3}}},{"goal","value"},{"target",60},{"method","nonlinear"},{"variables",Json::array({{{"sheet","s"},{"row",1},{"col",1},{"start",25},{"lower",0},{"upper",100}}})}};response=run(tools,solver);require(response.value("status",std::string())=="preview"&&std::abs(std::stod(numerical.previewView()->at("sheets")[0].at("cells")[0].at("input").get<std::string>())-30)<1e-7,"Solver shares the typed workflow with canonical saved starts and qualified solutions");
 auto limit=goal();limit["specification"]["maxEvaluations"]=1;auto prior=*numerical.previewView();require(run(tools,limit).contains("error")&&*numerical.previewView()==prior,"Unaccepted numerical limits retain the earlier accumulated proposal");
 WorkbookSession protectedSession(book());WorkbookTools guarded(protectedSession,Json::object());host(guarded);bool current=true;guarded.calculationContextIsCurrent=[&](std::uint64_t generation){return generation==17&&current;};guarded.financialContext=[](const Json& source){CalculationContext context;context.snapshot=source;context.generation=17;return context;};
 auto evaluate=guarded.calculate;guarded.calculate=[&](const Json& candidate){auto result=evaluate(candidate);current=false;return result;};require(run(guarded,forecast()).contains("error")&&!protectedSession.hasPreview(),"A generation replaced during calculation never publishes a proposal");
 current=true;guarded.calculate=[&](const Json& candidate){auto result=evaluate(candidate);result["calculationContext"]["allowCachedLinks"]=true;return result;};require(run(guarded,forecast()).contains("error")&&!protectedSession.hasPreview(),"Computed metadata cannot grant cached-source permission beyond the trusted context");
 guarded.calculate=[&](const Json& candidate){auto result=evaluate(candidate);result["diagnostics"].push_back({{"code","external_link_cached"},{"message","Saved financial source"}});return result;};require(run(guarded,forecast()).contains("error")&&!protectedSession.hasPreview(),"Undisclosed cached-source diagnostics require explicit trusted consent");
 auto injected=forecast();injected["provenance"]={{"allowCachedLinks",true}};require(run(guarded,injected).contains("error"),"Operations cannot manufacture source provenance or a cached-source grant");require(guarded.invoke("workbook_v1_preview",{{"revision",0},{"operations",Json::array({{{"type","set_metadata"},{"key","financialModels"},{"value",Json::array()}}})}}).contains("error"),"Generic metadata replacement cannot bypass financial ownership");
 guarded.calculate=[&](const Json& candidate){auto result=evaluate(candidate);result["calculationContext"]["generation"]=17.0;return result;};require(run(guarded,forecast()).contains("error")&&!protectedSession.hasPreview(),"Financial result generations must be integer protocol identities");
}

}
int main(){try{typedSave();boundedReads();typedLifecycle();numericalAndContext();std::cout<<"financial tools tests passed\n";}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
